"""Which adapter a port uses, read at each call: the environment variable, else the `env` of the project's `.claude/settings.local.json`, then `settings.json`,
in the current git root, then the main checkout (a worktree has no local settings), else the default. A process started before the setting was written still follows it."""
import json
import os
import pathlib
import subprocess

FILES = ("settings.local.json", "settings.json")


def git(*argv):
    try:
        run = subprocess.run(["git", *argv], capture_output=True, text=True)
    except OSError:
        return None
    return pathlib.Path(run.stdout.strip()) if run.returncode == 0 and run.stdout.strip() else None


def roots():
    """The current git root, then the main checkout."""
    top, common = git("rev-parse", "--show-toplevel"), git("rev-parse", "--path-format=absolute", "--git-common-dir")
    main = common.parent if common and common.name == ".git" else None
    return [p for i, p in enumerate([top, main]) if p and p not in [top, main][:i]]


def name(variable, default="github"):
    """VARIABLE's value for the port: the environment's, else the settings files', else DEFAULT."""
    if os.environ.get(variable):
        return os.environ[variable]
    for root in roots():
        for file in FILES:
            try:
                value = json.loads((root / ".claude" / file).read_text())["env"][variable]
            except (OSError, ValueError, KeyError, TypeError):
                continue
            if isinstance(value, str) and value:
                return value
    return default
